using System.ComponentModel;
using System.Net;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build IChatClient through MEAI abstraction ---
IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .Build();

// --- Register tools ---
var researchTools = new ResearchTools();
var tools = new AIFunctionFactory[]
{
}.ToList<object>();

var searchTool = AIFunctionFactory.Create(researchTools.SearchWebAsync);
var addNoteTool = AIFunctionFactory.Create(researchTools.AddNote);
var readNotesTool = AIFunctionFactory.Create(researchTools.ReadNotes);

// --- Create the agent ---
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research assistant that searches the web and takes notes.",
    Instructions = """
        You are a research agent. When given a topic you MUST:
        1. Use the SearchWeb tool 2-3 times with different queries to gather information.
        2. Use the AddNote tool to record each important finding as a separate note.
        3. Use the ReadNotes tool to review all collected notes.
        4. Produce a concise summary with key findings, organized by theme.
        Always cite which search queries produced each finding.
        """,
    Tools = { searchTool, addNoteTool, readNotesTool },
};

// --- Run the agent loop ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");
Console.WriteLine($"Notes collected: {researchTools.NoteCount}");

// --- Tool implementations ---

public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public int NoteCount => _notes.Count;

    [Description("Searches the web for a query and returns relevant result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Lite (HTML) as a free search source.
            var encoded = WebUtility.UrlEncode(query);
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://lite.duckduckgo.com/lite/?q={encoded}");
            request.Headers.UserAgent.ParseAdd(
                "ResearchAgent/1.0 (compatible; bot)");

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();

            // Extract text snippets from the result table rows.
            var snippets = ExtractSnippets(html, maxSnippets: 6);

            if (snippets.Count == 0)
            {
                return $"No results found for \"{query}\".";
            }

            return $"Search results for \"{query}\":\n" +
                   string.Join("\n", snippets.Select((s, i) => $"  {i + 1}. {s}"));
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    [Description("Adds a research note. Use to record an important finding.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Reads all previously saved research notes.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        return "Saved notes:\n" +
               string.Join("\n", _notes.Select((n, i) => $"  [{i + 1}] {n}"));
    }

    private static List<string> ExtractSnippets(string html, int maxSnippets)
    {
        var snippets = new List<string>();

        // DuckDuckGo Lite returns snippets in <td> elements with class "result-snippet".
        const string marker = "class=\"result-snippet\">";
        var idx = 0;

        while (snippets.Count < maxSnippets &&
               (idx = html.IndexOf(marker, idx, StringComparison.Ordinal)) >= 0)
        {
            idx += marker.Length;
            var end = html.IndexOf("</td>", idx, StringComparison.Ordinal);
            if (end < 0) break;

            var raw = html[idx..end];
            // Strip HTML tags and decode entities.
            var text = System.Text.RegularExpressions.Regex.Replace(raw, "<[^>]+>", "");
            text = WebUtility.HtmlDecode(text).Trim();

            if (text.Length > 20)
            {
                snippets.Add(text.Length > 300 ? text[..300] + "…" : text);
            }
        }

        return snippets;
    }
}

